(() => {
 const reduced=document.documentElement.dataset.motion==='reduced';
 const progress=document.createElement('div');progress.className='scroll-progress';progress.setAttribute('role','progressbar');progress.setAttribute('aria-label','Page scroll progress');progress.setAttribute('aria-valuemin','0');progress.setAttribute('aria-valuemax','100');document.body.append(progress);
 let scrollTarget=0,scrollCurrent=0,scrollFrame=0,scrollTime=0;
 function drawScroll(now){scrollFrame=0;const dt=scrollTime?Math.min(48,now-scrollTime):16;scrollTime=now;scrollCurrent=reduced?scrollTarget:scrollCurrent+(scrollTarget-scrollCurrent)*(1-Math.exp(-dt/65));if(Math.abs(scrollCurrent-scrollTarget)<.0001)scrollCurrent=scrollTarget;progress.style.transform='translateZ(0) scaleX('+scrollCurrent+')';progress.style.setProperty('--scroll-progress',scrollCurrent);progress.setAttribute('aria-orientation',matchMedia('(max-width:640px)').matches?'vertical':'horizontal');progress.setAttribute('aria-valuenow',Math.round(scrollCurrent*100));if(scrollCurrent!==scrollTarget)scrollFrame=requestAnimationFrame(drawScroll);else scrollTime=0;}
 function update(event){const target=event?.target;let max=document.documentElement.scrollHeight-innerHeight,position=scrollY;if(target?.classList?.contains('partner-fields')){max=target.scrollHeight-target.clientHeight;position=target.scrollTop;}scrollTarget=max?Math.max(0,Math.min(1,position/max)):0;if(!scrollFrame)scrollFrame=requestAnimationFrame(drawScroll);}document.addEventListener('scroll',update,{passive:true,capture:true});addEventListener('resize',update);new ResizeObserver(()=>update()).observe(document.body);update();
 if(!reduced){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target);}}),{threshold:.08});document.querySelectorAll('.champ-section-head,.champ-feature,.champ-story,.champ-partner,.champ-faq details,.gallery-frame,.resource-grid>a,#whats-on>ul>li').forEach((el,i)=>{el.classList.add('reveal-ready');el.style.transitionDelay=(i%3)*75+'ms';observer.observe(el);});
 if(matchMedia('(pointer: fine)').matches){const cursor=document.createElement('div');cursor.className='motion-cursor';cursor.textContent='VIEW ↗';cursor.setAttribute('aria-hidden','true');document.body.append(cursor);document.addEventListener('pointermove',e=>{cursor.style.transform=`translate(${e.clientX-36}px,${e.clientY-36}px)`;});document.querySelectorAll('.gallery-frame').forEach(el=>{el.addEventListener('pointerenter',()=>cursor.classList.add('on'));el.addEventListener('pointerleave',()=>cursor.classList.remove('on'));});}}
 // Restore the original tenant background slideshow using local media only.
 const slides=[...document.querySelectorAll('img[aria-hidden="true"].transition-opacity')];let slide=0;
 if(slides.length>1&&!reduced)setInterval(()=>{if(document.documentElement.classList.contains('slideshow-paused')||document.hidden)return;slides[slide].style.opacity='0';slide=(slide+1)%slides.length;slides[slide].style.opacity='1';},6500);
 const frames=[...document.querySelectorAll('.gallery-frame')],dialog=document.querySelector('#gallery-dialog');
 if(dialog){let index=0,origin;const image=dialog.querySelector('img'),caption=dialog.querySelector('#gallery-caption');function render(){image.src=frames[index].querySelector('img').src;image.alt=frames[index].querySelector('img').alt;caption.textContent=String(index+1).padStart(2,'0')+' / '+frames.length+' — '+image.alt;}
 frames.forEach((frame,i)=>frame.addEventListener('click',()=>{index=i;origin=frame;render();dialog.showModal();document.body.style.overflow='hidden';}));dialog.querySelector('#gallery-prev').addEventListener('click',()=>{index=(index-1+frames.length)%frames.length;render();});dialog.querySelector('#gallery-next').addEventListener('click',()=>{index=(index+1)%frames.length;render();});dialog.querySelector('#gallery-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{document.body.style.overflow='';origin?.focus();});dialog.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){index=(index+1)%frames.length;render();}if(e.key==='ArrowLeft'){index=(index-1+frames.length)%frames.length;render();}});}
})();
